import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const e="/img/math-restoration-2.svg",g=JSON.parse('{"title":"小学奥数进阶：还原问题的逆向思维","description":"还原问题又叫“倒推法”。本文通过流程图解，带你掌握如何从结果出发，一步步“反向操作”回到起点。","frontmatter":{"title":"小学奥数进阶：还原问题的逆向思维","date":"2026-02-08T10:10:00.000Z","categories":["数学"],"tags":["小学数学","奥数","还原问题"],"description":"还原问题又叫“倒推法”。本文通过流程图解，带你掌握如何从结果出发，一步步“反向操作”回到起点。","cover":"/img/math-restoration-2.svg","top_img":"/img/math-restoration-2.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-restoration-2.md","filePath":"posts/primary-math-olympiad-restoration-2.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-restoration-2.md"};function r(o,a,p,i,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="小学奥数进阶-还原问题的逆向思维" tabindex="-1">小学奥数进阶：还原问题的逆向思维 <a class="header-anchor" href="#小学奥数进阶-还原问题的逆向思维" aria-label="Permalink to &quot;小学奥数进阶：还原问题的逆向思维&quot;">​</a></h1><h2 id="一、-什么是还原问题" tabindex="-1">一、 什么是还原问题？ <a class="header-anchor" href="#一、-什么是还原问题" aria-label="Permalink to &quot;一、 什么是还原问题？&quot;">​</a></h2><p>还原问题是指已知一个数经过一系列变化（加、减、乘、除）后的最终结果，求这个数是多少的问题。</p><p><strong>核心思想</strong>：从结果出发，逆着变化的顺序，用相反的运算方法一步步推回去。</p><hr><h2 id="二、-核心规则-反向操作" tabindex="-1">二、 核心规则：反向操作 <a class="header-anchor" href="#二、-核心规则-反向操作" aria-label="Permalink to &quot;二、 核心规则：反向操作&quot;">​</a></h2><ul><li><strong>加 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>↔</mo></mrow><annotation encoding="application/x-tex">\\leftrightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">↔</span></span></span></span> 减</strong></li><li><strong>乘 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>↔</mo></mrow><annotation encoding="application/x-tex">\\leftrightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.36687em;"></span><span class="strut bottom" style="height:0.36687em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">↔</span></span></span></span> 除</strong></li></ul><hr><h2 id="三、-典型例题拆解" tabindex="-1">三、 典型例题拆解 <a class="header-anchor" href="#三、-典型例题拆解" aria-label="Permalink to &quot;三、 典型例题拆解&quot;">​</a></h2><h3 id="_1-基础还原" tabindex="-1">1. 基础还原 <a class="header-anchor" href="#_1-基础还原" aria-label="Permalink to &quot;1. 基础还原&quot;">​</a></h3><p><strong>例题</strong>：一个数加上 5，乘以 2，减去 8，最后除以 4，结果是 3。求这个数。</p><p><strong>解析</strong>：</p><ol><li><strong>正向过程</strong>：x \\xrightarrow{+5} \\dots \\xrightarrow{\\times 2} \\dots \\xrightarrow{-8} \\dots \\xrightarrow{\\div 4} 3</li><li><strong>逆向还原</strong>： <ul><li>第四步结果是 3，反推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">3 \\times 4 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span></li><li>第三步结果是 12，反推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mo>+</mo><mn>8</mn><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">12 + 8 = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span></li><li>第二步结果是 20，反推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\div 2 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span></li><li>第一步结果是 10，反推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>−</mo><mn>5</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">10 - 5 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span></li></ul></li></ol><ul><li><strong>结论</strong>：这个数是 <strong>5</strong>。</li></ul><p><img src="'+e+'" alt="还原问题逆向图解"></p><h3 id="_2-分数还原-吃苹果问题" tabindex="-1">2. 分数还原（吃苹果问题） <a class="header-anchor" href="#_2-分数还原-吃苹果问题" aria-label="Permalink to &quot;2. 分数还原（吃苹果问题）&quot;">​</a></h3><p><strong>例题</strong>：一篮苹果，第一天吃了全部的一半多 1 个，第二天吃了剩下的一半多 1 个，这时还剩 1 个。原来有多少个苹果？</p><p><strong>解析</strong>：</p><ul><li><strong>最后状态</strong>：剩 1 个。</li><li><strong>逆推第二天</strong>： <ul><li>“吃了剩下的一半多 1 个” 意味着：(剩下 - 1) \\div 2 = 1</li><li>反推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">1 + 1 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">2 \\times 2 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span>（即第二天开始前有 4 个）。</li></ul></li><li><strong>逆推第一天</strong>： <ul><li>“吃了全部的一半多 1 个” 意味着：(全部 - 1) \\div 2 = 4</li><li>反推：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">4 + 1 = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">5</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">5 \\times 2 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>。</li></ul></li><li><strong>结论</strong>：原来有 <strong>10</strong> 个。</li><li><strong>验证</strong>：10 吃一半加1是 6，剩 4；4 吃一半加1是 3，剩 1。正确！</li></ul><hr><h2 id="四、-解题技巧总结" tabindex="-1">四、 解题技巧总结 <a class="header-anchor" href="#四、-解题技巧总结" aria-label="Permalink to &quot;四、 解题技巧总结&quot;">​</a></h2><ol><li><strong>画流程图</strong>：清晰标注每一步的变化。</li><li><strong>逆序操作</strong>：从最后一个数开始，从后往前。</li><li><strong>运算取反</strong>：看到加法变减法，看到除法变乘法。</li></ol><hr><h2 id="五、-举一反三-练习题" tabindex="-1">五、 举一反三（练习题） <a class="header-anchor" href="#五、-举一反三-练习题" aria-label="Permalink to &quot;五、 举一反三（练习题）&quot;">​</a></h2><ol><li>某人去银行取款。第一次取了存款的一半多 50 元，第二次取了余下的一半多 100 元，这时存款还剩 1250 元。他原来存款多少元？</li><li>甲乙丙三个桶里共有油 24 千克。如果从甲桶倒出和乙桶同样多的油放入乙桶，再从乙桶倒出和丙桶同样多的油放入丙桶，最后从丙桶倒出和甲桶此时同样多的油放入甲桶，这时三桶油一样多。原来每桶各有多少油？</li></ol><hr><p><em>记住：还原问题就是“录像机倒带”！</em></p>',27)])])}const u=s(l,[["render",r]]);export{g as __pageData,u as default};
